export default async function campaign(
  { website, source, medium, name, term, campaignId, acknowledge, resolution },
  ctx,
) {
  const u = new URL(website);
  if (!["https:", "http:"].includes(u.protocol)) throw Error("Configure a valid website URL");
  for (const [k, v] of Object.entries({
    utm_source: source,
    utm_medium: medium,
    utm_campaign: name,
    utm_term: term,
    utm_content: campaignId,
  }))
    u.searchParams.set(k, v);
  const url = u.toString(),
    key = "campaign:" + url;
  let s = await ctx.state.get(key);
  if (s?.status === "pending") {
    if (acknowledge !== key || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect Airtable pending write " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return {
        url,
        qrUrl:
          "https://quickchart.io/qr?" +
          new URLSearchParams({
            text: url,
            size: "300",
            margin: "10",
            ecLevel: "H",
            dark: "000000",
            light: "FFFFFF",
          }),
        records: [{ fields: { URL: url } }],
        write: false,
        key,
      };
    }
  }
  if (s?.status === "done")
    return {
      url,
      qrUrl:
        "https://quickchart.io/qr?" +
        new URLSearchParams({
          text: url,
          size: "300",
          margin: "10",
          ecLevel: "H",
          dark: "000000",
          light: "FFFFFF",
        }),
      records: [{ fields: { URL: url } }],
      write: false,
      key,
    };
  await ctx.state.set(key, { status: "pending" });
  return {
    url,
    qrUrl:
      "https://quickchart.io/qr?" +
      new URLSearchParams({
        text: url,
        size: "300",
        margin: "10",
        ecLevel: "H",
        dark: "000000",
        light: "FFFFFF",
      }),
    records: [{ fields: { URL: url } }],
    write: true,
    key,
  };
}

