export default async function confirm({ key, records }, ctx) {
  if (!Array.isArray(records) || records.length !== 1 || !records[0]?.id)
    throw Error("Airtable create not confirmed");
  await ctx.state.set(key, { status: "done" });
  return { ok: true };
}

