export default async function report({ report }, ctx) {
  const rows = report?.rows;
  if (!Array.isArray(rows)) throw Error("Invalid GA4 report");
  return {
    facts: JSON.stringify({
      range: "last seven days through today",
      dimension: "sourceMedium",
      metric: "sessions",
      rowCount: report.rowCount,
      rows: rows.map((r) => ({
        sourceMedium: r.dimensionValues?.[0],
        sessions: r.metricValues?.[0],
      })),
    }),
  };
}

