export default async function reserve({ recipient, body, acknowledge, resolution }, ctx) {
  if (!recipient || !body) throw Error("Configure a recipient and report");
  const day = new Date().toISOString().slice(0, 10),
    key = "report:" + day;
  let s = await ctx.state.get(key);
  if (s?.status === "pending") {
    if (key !== acknowledge || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect Gmail pending write " + key);
    if (resolution === "confirmed") {
      await ctx.state.set(key, { status: "done" });
      return { key, recipient, body, write: false };
    }
  }
  if (s?.status === "done") return { key, recipient, body, write: false };
  await ctx.state.set(key, { status: "pending" });
  return { key, recipient, body, write: true };
}

